export type IconProps = Pick<
  ComponentProps<'svg'>,
  'width' | 'height' | 'className' | 'aria-hidden' | 'aria-label' | 'role'
> & {
  // Light is the cockpit's only icon weight, so this can restate the pin but never
  // change it. Kept until `roster/SessionRow.tsx` (owned by #3) drops the prop.
  weight?: 'light'
}

export type IconAtom = (props: IconProps) => React.JSX.Element

// The one place the cockpit's icon voice is pinned: Phosphor Light, in the shared
// `icon` box. Weight and fill never encode state — the enclosing element's
// currentColor does — so no icon file gets a say in either.
export function createIcon(Glyph: PhosphorIcon): IconAtom {
  function Icon({ className, ...rest }: IconProps): React.JSX.Element {
    return <Glyph {...rest} className={cn('icon', className)} weight="light" />
  }
  Icon.displayName = Glyph.displayName
  return Icon
}

import { useState } from 'react'

export type DisclosureProps = {
  /** Drives the state directly — once passed, the component only ever reports intent via
   * `onOpenChange` and never flips itself. */
  open?: boolean
  /** Seeds the internal state when uncontrolled. Ignored once `open` is passed. */
  defaultOpen?: boolean
  /** Every open/closed transition, whether the caller controls it or not. */
  onOpenChange?: (open: boolean) => void
}

/** The controlled-with-uncontrolled-fallback boolean any drawer/disclosure in the cockpit can
 * share: standalone it tracks its own open state seeded by `defaultOpen`; handed `open`, a
 * container drives it and `toggle` only reports through `onOpenChange`. */
export function useDisclosure({
  open,
  defaultOpen = false,
  onOpenChange,
}: DisclosureProps): [boolean, () => void] {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isControlled = open !== undefined
  const resolvedOpen = isControlled ? open : uncontrolledOpen

  function toggle(): void {
    const next = !resolvedOpen
    if (!isControlled) setUncontrolledOpen(next)
    onOpenChange?.(next)
  }

  return [resolvedOpen, toggle]
}

