/** What a row with no pixels says. Every branch is a different FACT about the same absence, so each
 * one is spelled out: a reader deciding whether to go and look at the file needs to know which. */
function absentReason(status: ToolCallStatus, media: MediaResult | null): string {
  if (media === null) {
    return status === 'pending' || status === 'in_progress'
      ? 'no image yet: this call has not come back'
      : 'no image: the record carried none for this call'
  }
  return media.tier === 'direct'
    ? 'no image to show: the record declared one but carried no readable bytes'
    : 'no image to show: the file is missing, deleted, or unreadable'
}

